function GlassBlowpipeCoolingRackMaker.completeMaking(m) local q=1.0+(GlassBlowpipeCoolingRackMaker.getQualityBonus()/100); if GlassBlowpipeCoolingRackMaker.maker then q=q+(GlassBlowpipeCoolingRackMaker.maker.skill/140) end; q=math.min(2.5,q); GlassBlowpipeCoolingRackMaker.productStock[m.productType]=(GlassBlowpipeCoolingRackMaker.productStock[m.productType] or 0)+m.quantity; GlassBlowpipeCoolingRackMaker.totalProducts=GlassBlowpipeCoolingRackMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if GlassBlowpipeCoolingRackMaker.maker then GlassBlowpipeCoolingRackMaker.maker.itemsMade=GlassBlowpipeCoolingRackMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then GlassBlowpipeCoolingRackMaker.maker.skill=math.min(100,GlassBlowpipeCoolingRackMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Polica izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"glassblowpipecoolingrack.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
